type Destination = {
	id: string; slug: string; name: string; category: string | null; categories: string[]; short_description: string; address: string | null; created_by: string | null;
	description: string; image_url: string | null; tags: string[]; mascot_mode?: "tiloc" | "custom"; mascot_image_url?: string | null; latitude: number | null; longitude: number | null; is_published: boolean; is_featured: boolean; created_at: string;
};
type Partner = { id: string; business_name: string; slug: string; destination_id: string | null; destination_name: string | null; max_distance_meters: number; business_type: string; business_categories: string[]; latitude: number | null; longitude: number | null; allow_minigame_integration: boolean; address: string | null; status: string; created_at: string };
type QrPoint = { id: string; destination_id: string; destination_name: string; name: string; code: string; address: string | null; latitude: number | null; longitude: number | null; is_active: boolean; created_at: string };
type Promotion = { id: string; partner_id: string | null; partner_name: string; qr_point_id: string | null; qr_label: string; title: string; experience_type: string; placement_mode: string; exposure_mode: string; status: string; approval_status: string; approval_feedback: string | null; starts_at: string | null; ends_at: string | null; created_at: string; has_form: boolean };
type CampaignMinigame = { id: string; destination_id: string; destination_name: string; name: string; slug: string; components: string[]; is_enabled: boolean };
type SessionMonitorData = {
	updatedAt: string;
	metrics: { sessionsToday: number; activeNow: number; averageDurationMinutes: number; busiestDestination: { name: string; count: number } | null };
	sessions: { id: string; visitorLabel: string; destinationName: string; startedAt: string; lastActivityAt: string; expiresAt: string; status: "active" | "expired" | "ended" }[];
};
type DestinationReview = { id: string; destination_id: string; manager_user_id: string; status: "pending" | "approved" | "changes_requested" | "taken_down"; feedback: string | null; submitted_at: string; created_at: string };
type StaffManagerSummary = { user_id: string; role: "editor" | "destination_manager"; email: string; has_confirmed_email: boolean; destination_ids: string[]; destination_names: string[] };

export type WorkspaceData = {
	role: "admin" | "editor" | "destination_manager";
	userId: string;
	email: string;
	destinations: Destination[];
	partners: Partner[];
	qrPoints: QrPoint[];
	promotions: Promotion[];
	minigames: CampaignMinigame[];
	reviewRequests: DestinationReview[];
	managedDestinationIds: string[];
	staffManagers: StaffManagerSummary[];
	staffInviteConfigured: boolean;
	staffInviteReadiness: { hasServiceKey: boolean; hasAppOrigin: boolean; databaseReady: boolean; appOrigin: string };
	staffManagerError?: string;
	driveConnected: boolean;
	driveConnectedEmail?: string;
	driveOwnerEmail: string;
	driveConfigured: boolean;
	driveNotice?: string;
	dataIssues: string[];
	driveIssue?: string;
};

type Section = "overview" | "destinations" | "qr" | "review" | "partners" | "promotions" | "analytics" | "sessions" | "guide" | "staff";
type CampaignIdea = { id: string; slug: string; name: string; views: number; visitors: number };
